impl SourceType {
    pub(crate) fn of_path(path: &str, package: Option<PackageType>) -> Option<Self> {
        let name = path.rsplit('/').next().unwrap_or(path);
        match name.rsplit_once('.').map(|(_, extension)| extension) {
            Some("cjs" | "cts") => Some(Self::CommonJs),
            Some("ts") if is_declaration_file(name) => Some(Self::Module),
            Some("js" | "jsx" | "ts") => match package {
                None | Some(PackageType::Module) => Some(Self::Module),
                Some(PackageType::CommonJs) => Some(Self::CommonJs),
                Some(PackageType::Unset) => None,
            },
            _ => Some(Self::Module),
        }
    }
}

fn ecma_label(path: &str) -> Option<&'static str> {
    let extension = path.rsplit_once('.')?.1.to_ascii_lowercase();
    match extension.as_str() {
        "ts" | "mts" | "cts" => Some("typescript"),
        "tsx" => Some("tsx"),
        "js" | "jsx" | "mjs" | "cjs" => Some("javascript"),
        _ => None,
    }
}

fn planned(language: &str) -> bool {
    for planned in ["vue", "sql", "rust"] {
        if planned == language { return true; }
    }
    false
}

