pub(crate) fn path_module(path: &str) -> Option<String> {
    let path = path
        .strip_suffix(".py")
        .or_else(|| path.strip_suffix(".pyi"))?;
    Some(path.replace('/', "."))
}

fn label(extension: &str) -> Option<&'static str> {
    match extension {
        "py" => Some("python"),
        "php" => Some("php"),
        _ => None,
    }
}

